1	package nexusbench
2	
3	import (
4		"context"
5		"fmt"
6		"slices"
7		"strings"
8		"testing"
9	)
10	
11	// The preflight of the seed and the three permissions `up` gains (DEVDESK-505,
12	// NX-02a, step 5). Against the scripted kubectl of preflight_test.go, which
13	// records every "auth can-i" question in order.
14	//
15	// Choices of the tests, to settle with the code:
16	//   - OpSeed is appended after OpStatus; no earlier value moves.
17	//   - A subresource is asked as kubectl wants it: `auth can-i create pods
18	//     --subresource=portforward -n <ns>`, never `create pods/portforward`, which
19	//     kubectl reads as the pod named "portforward". The fake fails the test on a
20	//     resource that holds a "/". The tests below write a question as
21	//     "<verb> <resource>[ --subresource=<sub>] -n <ns>" (see asked), and the
22	//     failure messages as "pods/portforward" or "pods --subresource=portforward"
23	//     alike: they only require each word (the verb, "pods", "portforward").
24	//     The Check of a refusal repeats the question: it contains
25	//     "auth can-i <verb> <resource>" and "--subresource=<sub>".
26	//   - The questions of seed, in this order, all in the bench namespace:
27	//     get deployments, list pods, get pods, get services, get
28	//     persistentvolumeclaims, list persistentvolumeclaims, create pods
29	//     --subresource=portforward, patch deployments --subresource=scale.
30	//     The port-forward to svc/bench-upstream reads the Service, then the pod,
31	//     before it POSTs to pods/portforward (get services, get pods, create
32	//     pods/portforward); EnsureUpstream observes the upstream's Deployment,
33	//     pods and claim on every turn of its wait (get deployments, list pods, get
34	//     and list persistentvolumeclaims) and scales it (patch deployments/scale).
35	//     Without the two claim questions a Forbidden would arrive after the scale
36	//     write. The order among them is the tests' choice.
37	//   - up keeps its fourteen questions where they are (they already hold get pods
38	//     and the claims) and asks the three new ones after them, in this order:
39	//     patch deployments --subresource=scale (EnsureUpstream), create pods
40	//     --subresource=portforward and get services (the port-forward the seed
41	//     opens). Its create pods/exec, inherited from NX-01, is asked the same way:
42	//     create pods --subresource=exec.
43	//   - seed refuses an absent or a foreign namespace, like provision and status,
44	//     does not read the Services of the cluster (that is up's NodePort check),
45	//     and does not read the nodes either: the seed reaches the registry through
46	//     a port-forward on the loopback and no question covers get nodes, so its
47	//     PreflightResult.NodeIP is empty. up and provision keep reading it.
48	//   - A refused question ends the preflight there: the later ones are not asked.
49	//   - Nothing is ever written.
50	
51	// asked renders the can-i questions the fake saw: "verb resource", plus
52	// "--subresource=<sub>" when there is one, plus "-n <ns>" or "-A" when the
53	// question was scoped.
54	func asked(f *fakeKubectl) []string {
55		out := make([]string, 0, len(f.asked))
56		for _, q := range f.asked {
57			s := q.verb + " " + q.resource
58			if q.subresource != "" {
59				s += " --subresource=" + q.subresource
60			}
61			switch {
62			case q.allNamespaces:
63				s += " -A"
64			case q.namespace != "":
65				s += " -n " + q.namespace
66			}
67			out = append(out, s)
68		}
69		return out
70	}
71	
72	func inNamespace(p Params, questions ...string) []string {
73		out := make([]string, 0, len(questions))
74		for _, q := range questions {
75			out = append(out, q+" -n "+p.Namespace)
76		}
77		return out
78	}
79	
80	// seedQuestions are the questions of OpSeed, in the order the tests expect.
81	var seedQuestions = []string{
82		"get deployments", "list pods", "get pods", "get services",
83		"get persistentvolumeclaims", "list persistentvolumeclaims",
84		"create pods --subresource=portforward", "patch deployments --subresource=scale",
85	}
86	
87	// seedDenials are the same questions as deny takes them, "pods/portforward".
88	var seedDenials = []struct{ verb, resource string }{
89		{"get", "deployments"},
90		{"list", "pods"},
91		{"get", "pods"},
92		{"get", "services"},
93		{"get", "persistentvolumeclaims"},
94		{"list", "persistentvolumeclaims"},
95		{"create", "pods/portforward"},
96		{"patch", "deployments/scale"},
97	}
98	
99	// requireRepeatsTheQuestion checks that a Check names the refused question the
100	// way kubectl takes it: the resource, and the subresource as a flag.
101	func requireRepeatsTheQuestion(t *testing.T, check, verb, resource string) {
102		t.Helper()
103		res, sub, hasSub := strings.Cut(resource, "/")
104		if want := "auth can-i " + verb + " " + res; !strings.Contains(check, want) {
105			t.Errorf("Check %q does not repeat the refused question %q", check, want)
106		}
107		if hasSub && !strings.Contains(check, "--subresource="+sub) {
108			t.Errorf("Check %q does not carry --subresource=%s", check, sub)
109		}
110		if strings.Contains(check, res+"/"+sub) {
111			t.Errorf("Check %q writes %s/%s, which kubectl reads as an object name", check, res, sub)
112		}
113	}
