115	func TestRunPreflightOpSeedIsAppended(t *testing.T) {
116		want := map[string]Op{"OpUp": 0, "OpProvision": 1, "OpDown": 2, "OpStatus": 3, "OpSeed": 4}
117		got := map[string]Op{"OpUp": OpUp, "OpProvision": OpProvision, "OpDown": OpDown, "OpStatus": OpStatus, "OpSeed": OpSeed}
118		for name, v := range want {
119			if got[name] != v {
120				t.Errorf("%s = %d, want %d: operations are appended, never renumbered", name, got[name], v)
121			}
122		}
123	}
