125	func TestRunPreflightSeedAsksItsQuestionsInOrder(t *testing.T) {
126		p := Defaults()
127		f := newFakeKubectl(t, p).ours()
128		res, err := RunPreflight(context.Background(), f, p, OpSeed)
129		if err != nil {
130			t.Fatalf("RunPreflight(OpSeed): %v", err)
131		}
132		want := inNamespace(p, seedQuestions...)
133		if got := asked(f); !slices.Equal(got, want) {
134			t.Errorf("questions =\n  %q\nwant\n  %q", got, want)
135		}
136		if want := (PreflightResult{NamespaceExists: true, NamespaceOurs: true}); res != want {
137			t.Errorf("result = %+v, want %+v", res, want)
138		}
139		for _, line := range f.callLines() {
140			if strings.HasPrefix(line, "get services") {
141				t.Errorf("seed read the Services of the cluster (%q): the NodePort check is up's", line)
142			}
143		}
144		requireReadOnly(t, f)
145	}
