147	func TestRunPreflightSeedDoesNotReadTheNodes(t *testing.T) {
148		// No can-i covers get nodes, and the seed has no use for the address: it
149		// reaches the registries through a port-forward on the loopback.
150		p := Defaults()
151		f := newFakeKubectl(t, p).ours()
152		res, err := RunPreflight(context.Background(), f, p, OpSeed)
153		if err != nil {
154			t.Fatalf("RunPreflight(OpSeed): %v", err)
155		}
156		for _, line := range f.callLines() {
157			if strings.Contains(line, "nodes") {
158				t.Errorf("seed issued %q: it must not read the nodes", line)
159			}
160		}
161		if res.NodeIP != "" {
162			t.Errorf("NodeIP = %q, want it empty for seed", res.NodeIP)
163		}
164		// up and provision are not affected: they still read it.
165		for _, op := range []Op{OpUp, OpProvision} {
166			f := newFakeKubectl(t, p).ours()
167			res, err := RunPreflight(context.Background(), f, p, op)
168			if err != nil {
169				t.Fatalf("RunPreflight(%s): %v", testOpName[op], err)
170			}
171			if res.NodeIP != fakeNodeIP || !slices.Contains(f.callLines(), "get nodes -o json") {
172				t.Errorf("%s: NodeIP = %q and calls %q, want it to read the nodes", testOpName[op], res.NodeIP, f.callLines())
173			}
174		}
175	}
