177	func TestRunPreflightSeedHonorsTheNamespaceParameter(t *testing.T) {
178		p := Defaults()
179		p.Namespace = "nexus-bench-2"
180		p.UpstreamURL = upstreamFor(p.Namespace)
181		f := newFakeKubectl(t, p).ours()
182		if _, err := RunPreflight(context.Background(), f, p, OpSeed); err != nil {
183			t.Fatalf("RunPreflight(OpSeed): %v", err)
184		}
185		if got := asked(f); len(got) != len(seedQuestions) {
186			t.Errorf("seed asked %d questions, want %d: %q", len(got), len(seedQuestions), got)
187		}
188		for _, q := range asked(f) {
189			if !strings.HasSuffix(q, " -n nexus-bench-2") {
190				t.Errorf("question %q is not scoped to the namespace of the run", q)
191			}
192		}
193		requireReadOnly(t, f)
194	}
