196	func TestRunPreflightUpAsksTheUpstreamQuestionsLast(t *testing.T) {
197		p := Defaults()
198		f := newFakeKubectl(t, p)
199		if _, err := RunPreflight(context.Background(), f, p, OpUp); err != nil {
200			t.Fatalf("RunPreflight(OpUp): %v", err)
201		}
202		got := asked(f)
203		if len(got) != len(requiredChecks[OpUp])+3 {
204			t.Fatalf("up asked %d questions, want the %d it asked before plus 3:\n%q", len(got), len(requiredChecks[OpUp]), got)
205		}
206		wantTail := inNamespace(p, "patch deployments --subresource=scale", "create pods --subresource=portforward", "get services")
207		if tail := got[len(got)-3:]; !slices.Equal(tail, wantTail) {
208			t.Errorf("the last three questions of up are %q, want %q", tail, wantTail)
209		}
210		// What up asked before is still asked, in the same places.
211		for _, c := range requiredChecks[OpUp] {
212			if !slices.ContainsFunc(f.asked[:len(f.asked)-3], func(q canIQuery) bool { return c.matches(q, p) }) {
213				t.Errorf("up no longer asks auth can-i %s %s (%s) before the new questions", c.verb, c.resource, c.scope)
214			}
215		}
216		requireReadOnly(t, f)
217	}
