219	func TestRunPreflightSeedStopsAtTheFirstRefusedQuestion(t *testing.T) {
220		p := Defaults()
221		all := inNamespace(p, seedQuestions...)
222		for i, d := range seedDenials {
223			t.Run(d.verb+" "+d.resource, func(t *testing.T) {
224				f := newFakeKubectl(t, p).ours().deny(d.verb, d.resource)
225				_, err := RunPreflight(context.Background(), f, p, OpSeed)
226				be := requireDeployKind(t, err, Forbidden)
227				requireMentions(t, err, append([]string{d.verb}, strings.Split(d.resource, "/")...), nil)
228				requireRepeatsTheQuestion(t, be.Check, d.verb, d.resource)
229				if got, want := asked(f), all[:i+1]; !slices.Equal(got, want) {
230					t.Errorf("questions = %q, want them to stop at the refused one: %q", got, want)
231				}
232				requireReadOnly(t, f)
233			})
234		}
235	}
