255	func TestRunPreflightAsksEverySubresourceAsAFlag(t *testing.T) {
256		// up asks create pods/exec (NX-01), patch deployments/scale and create
257		// pods/portforward; provision asks create pods/exec; seed asks the last two.
258		want := map[Op][]string{
259			OpUp:        {"create pods --subresource=exec", "patch deployments --subresource=scale", "create pods --subresource=portforward"},
260			OpProvision: {"create pods --subresource=exec"},
261			OpSeed:      {"create pods --subresource=portforward", "patch deployments --subresource=scale"},
262		}
263		for op, questions := range want {
264			t.Run(testOpName[op], func(t *testing.T) {
265				p := Defaults()
266				f := newFakeKubectl(t, p).ours()
267				if _, err := RunPreflight(context.Background(), f, p, op); err != nil {
268					t.Fatalf("RunPreflight: %v", err)
269				}
270				got := asked(f)
271				for _, q := range questions {
272					if !slices.Contains(got, q+" -n "+p.Namespace) {
273						t.Errorf("never asked %q in the namespace; asked %q", q, got)
274					}
275				}
276				for _, line := range f.callLines() {
277					if strings.Contains(line, "auth can-i") && strings.Contains(strings.TrimPrefix(line, "auth can-i "), "/") {
278						t.Errorf("%q puts a subresource in the resource", line)
279					}
280				}
281				requireReadOnly(t, f)
282			})
283		}
284	}
