330	func TestRunPreflightSeedStopsBeforeTheQuestionsOnABadCluster(t *testing.T) {
331		tests := []struct {
332			name  string
333			setup func(f *fakeKubectl)
334			kind  ErrKind
335		}{
336			{"unknown context", func(f *fakeKubectl) { f.contexts = "k0s\nminikube\n" }, ContextNotFound},
337			{"API server down", func(f *fakeKubectl) {
