178	type preflight struct {
179		r Runner
180		p Params
181	}
182	
183	// local runs a call that does not reach the API server.
184	func (pf preflight) local(ctx context.Context, args ...string) (stdout, stderr string, err error) {
185		out, errOut, err := pf.r.Run(ctx, nil, args...)
186		return string(out), string(errOut), err
187	}
188	
189	// remote runs a call that reaches the API server, under a request timeout.
190	func (pf preflight) remote(ctx context.Context, args ...string) (stdout, stderr string, err error) {
191		return pf.local(ctx, slices.Concat(args, []string{requestTimeout})...)
192	}
193	
194	// command is the kubectl command line a user can run to repeat a call.
195	func (pf preflight) command(args ...string) string {
196		return "kubectl --context " + pf.p.Context + " " + strings.Join(args, " ")
197	}
198	
199	// failure turns a failed kubectl call into a BenchError whose kind comes from
200	// the stderr. Neither the stderr nor the sub-process error reaches the message.
201	func (pf preflight) failure(what string, args []string, stderr string, err error) *BenchError {
202		kind := classifyKubectl(stderr)
203		reason := "kubectl failed"
204		switch kind {
205		case Forbidden:
206			reason = "the API server refused the request (forbidden)"
207		case ClusterUnreachable:
208			reason = "the cluster did not answer"
209		}
210		return &BenchError{
211			Kind:  kind,
212			Cause: "could not " + what + ": " + reason,
213			Check: pf.command(args...),
214			Err:   err,
215		}
216	}
