218	func (pf preflight) checkContext(ctx context.Context) error {
219		args := []string{"config", "get-contexts", "-o", "name"}
220		out, errOut, err := pf.local(ctx, args...)
221		if err != nil {
222			return pf.failure("list the kubeconfig contexts", args, errOut, err)
223		}
224		for _, line := range strings.Split(out, "\n") {
225			if strings.TrimSpace(line) == pf.p.Context {
226				return nil
227			}
228		}
229		return &BenchError{
230			Kind:  ContextNotFound,
231			Cause: fmt.Sprintf("no kubeconfig context is named %q", pf.p.Context),
232			Check: "kubectl config get-contexts -o name, then set NEXUS_BENCH_CONTEXT to one of them",
233		}
234	}
235	
236	func (pf preflight) checkReachable(ctx context.Context) error {
237		args := []string{"get", "--raw", "/readyz"}
238		_, errOut, err := pf.remote(ctx, args...)
239		if err == nil {
240			return nil
241		}
242		// A refusal (an expired token, a 403) is not an absent cluster: say so.
243		// Anything else, classified or not, means the server did not answer.
244		if classifyKubectl(errOut) == Forbidden {
245			return pf.failure("reach the API server", args, errOut, err)
246		}
247		return &BenchError{
248			Kind:  ClusterUnreachable,
249			Cause: fmt.Sprintf("the API server of context %q does not answer /readyz", pf.p.Context),
250			Check: pf.command(args...),
251			Err:   err,
252		}
253	}
254	
255	// checkPermission asks "kubectl auth can-i". A "no" arrives on stdout with a
256	// non-zero exit, so the answer is read before the error.
257	func (pf preflight) checkPermission(ctx context.Context, perm permission) error {
258		args := []string{"auth", "can-i", perm.verb, perm.resource}
259		if perm.subresource != "" {
260			args = append(args, "--subresource="+perm.subresource)
261		}
262		where := "cluster-wide"
263		switch perm.scope {
264		case scopeNamespace:
265			args = append(args, "-n", pf.p.Namespace)
266			where = fmt.Sprintf("in namespace %q", pf.p.Namespace)
267		case scopeAll:
268			args = append(args, "-A")
269			where = "in all namespaces"
270		}
271		out, errOut, err := pf.remote(ctx, args...)
272		answer := strings.TrimSpace(out)
273		switch {
274		case strings.HasPrefix(answer, "no"):
275			return &BenchError{
276				Kind:  Forbidden,
277				Cause: fmt.Sprintf("the current user is not allowed to %s %s %s", perm.verb, perm.name(), where),
278				Check: pf.command(args...),
279				Err:   err,
280			}
281		case err == nil && strings.HasPrefix(answer, "yes"):
282			return nil
283		}
284		return pf.failure(fmt.Sprintf("check the permission to %s %s", perm.verb, perm.name()), args, errOut, err)
285	}
