287	// namespaceObject is the part of a Namespace the preflight reads.
288	type namespaceObject struct {
289		Metadata struct {
290			Labels map[string]string `json:"labels"`
291		} `json:"metadata"`
292	}
293	
294	func (pf preflight) checkNamespace(ctx context.Context, op Op) (PreflightResult, error) {
295		var res PreflightResult
296		ns := pf.p.Namespace
297		args := []string{"get", "namespace", ns, "-o", "json"}
298		out, errOut, err := pf.remote(ctx, args...)
299		switch {
300		case err != nil && isNotFound(errOut):
301			// Absent: only provision, status and seed need it.
302			if op == OpProvision || op == OpStatus || op == OpSeed {
303				return res, &BenchError{
304					Kind:  NamespaceMissing,
305					Cause: fmt.Sprintf("namespace %q does not exist", ns),
306					Check: pf.command(args[:3]...) + ", then run `mise run nexus-bench:up`",
307					Err:   err,
308				}
309			}
310			return res, nil
311		case err != nil:
312			return res, pf.failure(fmt.Sprintf("read the namespace %q", ns), args, errOut, err)
313		}
314	
315		var obj namespaceObject
316		if err := json.Unmarshal([]byte(out), &obj); err != nil {
317			return res, &BenchError{
318				Kind:  Unclassified,
319				Cause: fmt.Sprintf("kubectl answered with something that is not a Namespace for %q", ns),
320				Check: pf.command(args...),
321				Err:   err,
322			}
323		}
324		res.NamespaceExists = true
325		res.NamespaceOurs = obj.Metadata.Labels[managedByLabel] == managedByValue
326		if !res.NamespaceOurs {
327			return res, &BenchError{
328				Kind:  NamespaceForeign,
329				Cause: fmt.Sprintf("namespace %q exists but does not carry the label %s=%s, so the bench did not create it", ns, managedByLabel, managedByValue),
330				Check: pf.command("get", "namespace", ns, "--show-labels") + ", or choose another NEXUS_BENCH_NAMESPACE",
331			}
332		}
333		return res, nil
334	}
