336	// serviceList is the part of a Service list the preflight reads.
337	type serviceList struct {
338		Items []struct {
339			Metadata struct {
340				Name      string `json:"name"`
341				Namespace string `json:"namespace"`
342			} `json:"metadata"`
343			Spec struct {
344				Ports []struct {
345					NodePort int `json:"nodePort"`
346				} `json:"ports"`
347			} `json:"spec"`
348		} `json:"items"`
349	}
