351	// checkNodePorts reads every Service of the cluster: the list of taken
352	// NodePorts is not a constant (F1). Our own Service, in our namespace, may hold
353	// them: that is a second up.
354	func (pf preflight) checkNodePorts(ctx context.Context) error {
355		args := []string{"get", "services", "-A", "-o", "json"}
356		out, errOut, err := pf.remote(ctx, args...)
357		if err != nil {
358			return pf.failure("list the Services of the cluster", args, errOut, err)
359		}
360		var list serviceList
361		if err := json.Unmarshal([]byte(out), &list); err != nil {
362			return &BenchError{
363				Kind:  Unclassified,
364				Cause: "kubectl answered with something that is not a Service list",
365				Check: pf.command(args...),
366				Err:   err,
367			}
368		}
369		var taken []string
370		for _, svc := range list.Items {
371			if svc.Metadata.Namespace == pf.p.Namespace && svc.Metadata.Name == nexusServiceName {
372				continue
373			}
374			for _, port := range svc.Spec.Ports {
375				if port.NodePort == pf.p.HTTPNodePort || port.NodePort == pf.p.DockerNodePort {
376					taken = append(taken, fmt.Sprintf("%d is held by Service %s/%s", port.NodePort, svc.Metadata.Namespace, svc.Metadata.Name))
377				}
378			}
379		}
380		if len(taken) > 0 {
381			return &BenchError{
382				Kind:  NodePortTaken,
383				Cause: "NodePort " + strings.Join(taken, ", "),
384				Check: pf.command(args...) + ", then set NEXUS_BENCH_HTTP_NODEPORT and NEXUS_BENCH_DOCKER_NODEPORT to free ports",
385			}
386		}
387		return nil
388	}
