391	type nodeList struct {
392		Items []struct {
393			Status struct {
394				Addresses []struct {
395					Type    string `json:"type"`
396					Address string `json:"address"`
397				} `json:"addresses"`
398			} `json:"status"`
399		} `json:"items"`
400	}
