402	// nodeIP returns the first InternalIP any node reports, or "" when none does.
403	func (pf preflight) nodeIP(ctx context.Context) (string, error) {
404		args := []string{"get", "nodes", "-o", "json"}
405		out, errOut, err := pf.remote(ctx, args...)
406		if err != nil {
407			return "", pf.failure("read the nodes", args, errOut, err)
408		}
409		var nodes nodeList
410		if err := json.Unmarshal([]byte(out), &nodes); err != nil {
411			return "", &BenchError{
412				Kind:  Unclassified,
413				Cause: "kubectl answered with something that is not a Node list",
414				Check: pf.command(args...),
415				Err:   err,
416			}
417		}
418		for _, node := range nodes.Items {
419			for _, addr := range node.Status.Addresses {
420				if addr.Type == "InternalIP" {
421					return addr.Address, nil
422				}
423			}
424		}
425		return "", nil
426	}
