75	// permissionsByOp is the list F2 of the plan: what each operation needs. An
76	// operation absent from the map (status) writes nothing and asks nothing.
77	var permissionsByOp = map[Op][]permission{
78		OpUp: {
79			{"create", "namespaces", "", scopeCluster},
80			{"create", "persistentvolumeclaims", "", scopeNamespace},
81			{"create", "services", "", scopeNamespace},
82			{"create", "deployments", "", scopeNamespace},
83			{"create", "pods", "exec", scopeNamespace},
84			{"list", "services", "", scopeAll},
85			// Server-side apply is a PATCH, also on a second run (the namespace
86			// included), and Deploy reads the pods and the claims of the namespace
87			// while it waits.
88			{"patch", "namespaces", "", scopeCluster},
89			{"patch", "deployments", "", scopeNamespace},
90			{"patch", "services", "", scopeNamespace},
91			{"patch", "persistentvolumeclaims", "", scopeNamespace},
92			{"get", "pods", "", scopeNamespace},
93			{"list", "pods", "", scopeNamespace},
94			{"get", "persistentvolumeclaims", "", scopeNamespace},
95			{"list", "persistentvolumeclaims", "", scopeNamespace},
96			// The upstream: EnsureUpstream scales it, and the seed that follows up
97			// reaches it through a port-forward, which reads the Service first. Asked
98			// last, so the fourteen above stay where they were.
99			{"patch", "deployments", "scale", scopeNamespace},
100			{"create", "pods", "portforward", scopeNamespace},
101			{"get", "services", "", scopeNamespace},
102		},
103		// Provision waits for the Deployment and reads the pods before it execs.
104		OpProvision: {
105			{"create", "pods", "exec", scopeNamespace},
106			{"get", "deployments", "", scopeNamespace},
107			{"list", "pods", "", scopeNamespace},
108		},
109		OpDown: {{"delete", "namespaces", "", scopeCluster}},
110		// Seed reads the Deployment and the pods of the upstream, scales it back
111		// when it is cut, and reaches it through a port-forward, which gets the
112		// Service, then the pod it picks, before it opens the tunnel. EnsureUpstream
113		// reads the claim on every turn of its wait, so the two claim questions come
114		// before the first write.
115		OpSeed: {
116			{"get", "deployments", "", scopeNamespace},
117			{"list", "pods", "", scopeNamespace},
118			{"get", "pods", "", scopeNamespace},
119			{"get", "services", "", scopeNamespace},
120			{"get", "persistentvolumeclaims", "", scopeNamespace},
121			{"list", "persistentvolumeclaims", "", scopeNamespace},
122			{"create", "pods", "portforward", scopeNamespace},
123			{"patch", "deployments", "scale", scopeNamespace},
124		},
