127	// RunPreflight checks, with read-only kubectl calls, that op can go ahead, and
128	// returns what it learned. Nothing is written to the cluster, whatever the
129	// outcome: a failure here means no write was ever issued. The checks run in a
130	// fixed order and stop at the first failure, so nothing is asked of a cluster
131	// the context does not reach:
132	//
133	//  1. the parameters (no call at all)
134	//  2. the context is in the kubeconfig
135	//  3. the API server answers /readyz
136	//  4. the can-i questions of the operation
137	//  5. the namespace: absent, ours, or foreign
138	//  6. up only: no other Service holds one of our NodePorts
139	//  7. all but down and seed: the InternalIP of the node
140	//
141	// Every failure is a *BenchError.
142	func RunPreflight(ctx context.Context, r Runner, p Params, op Op) (PreflightResult, error) {
143		var res PreflightResult
144		if err := p.Validate(); err != nil {
145			return res, err
146		}
147		pf := preflight{r: r, p: p}
148		if err := pf.checkContext(ctx); err != nil {
149			return res, err
150		}
151		if err := pf.checkReachable(ctx); err != nil {
152			return res, err
153		}
154		for _, perm := range permissionsByOp[op] {
155			if err := pf.checkPermission(ctx, perm); err != nil {
156				return res, err
157			}
158		}
159		res, err := pf.checkNamespace(ctx, op)
160		if err != nil {
161			return res, err
162		}
163		if op == OpUp {
164			if err := pf.checkNodePorts(ctx); err != nil {
165				return res, err
166			}
167		}
168		// The seed reaches the registries through a port-forward on the loopback: it
169		// has no use for the node address and no can-i question covers get nodes.
170		if op != OpDown && op != OpSeed {
171			if res.NodeIP, err = pf.nodeIP(ctx); err != nil {
172				return res, err
173			}
174		}
175		return res, nil
176	}
