104	// answers, every can-i is "yes", the namespace does not exist, and the Services
105	// are those of the real cluster on 2026-11-16 (F1 of the plan).
106	func newFakeKubectl(t *testing.T, p Params) *fakeKubectl {
107		t.Helper()
108		return &fakeKubectl{
109			t:        t,
110			p:        p,
111			contexts: "k0s\n" + p.Context + "\nminikube\n",
112			readyz:   fakeReply{stdout: "ok"},
113			denied:   map[string]bool{},
114			services: []fakeService{
115				{"default", "kubernetes", nil},
116				{"traefik", "traefik", []int{30080}},
117				{"observability", "grafana", []int{30300}},
118				{"plane", "plane-web", []int{30890}},
119				{"plane", "plane-api", []int{30891, 30892}},
120				{"kube-system", "kube-dns", nil},
121			},
122			nodeAddresses: [][2]string{{"Hostname", "datomir"}, {"InternalIP", fakeNodeIP}},
123		}
124	}
