126	// withNamespace makes the bench namespace exist, with the given labels.
127	func (f *fakeKubectl) withNamespace(labels map[string]string) *fakeKubectl {
128		f.nsPresent = true
129		f.nsLabels = labels
130		return f
131	}
132	
133	// ours is the namespace as the bench creates it, plus the label every
134	// namespace gets from the API server.
135	func (f *fakeKubectl) ours() *fakeKubectl {
136		return f.withNamespace(map[string]string{
137			managedByKV:                   benchOwner,
138			"app.kubernetes.io/part-of":   benchOwner,
139			"kubernetes.io/metadata.name": f.p.Namespace,
140		})
141	}
142	
143	func (f *fakeKubectl) deny(verb, resource string) *fakeKubectl {
144		f.denied[verb+" "+resource] = true
145		return f
146	}
147	
148	func (f *fakeKubectl) addService(namespace, name string, nodePorts ...int) *fakeKubectl {
149		f.services = append(f.services, fakeService{namespace, name, nodePorts})
150		return f
