152	
153	// Run implements Runner.
154	func (f *fakeKubectl) Run(_ context.Context, stdin []byte, args ...string) (stdout, stderr []byte, err error) {
155		f.calls = append(f.calls, fakeCall{args: slices.Clone(args), stdin: slices.Clone(stdin)})
156		if slices.Contains(args, "--context") {
157			f.t.Errorf("kubectl call %q passes --context itself: the runner injects it", args)
158		}
159		if verb := verbOf(args); isWriteVerb(verb) {
160			return nil, []byte("the fake refuses a write: " + verb), errFakeExit1
161		}
162	
163		norm := normalizeArgs(args)
164		switch joined := strings.Join(norm, " "); {
165		case joined == "config get-contexts -o name":
166			return []byte(f.contexts), nil, nil
167		case joined == "get --raw /readyz":
168			return f.readyz.reply()
169		case strings.HasPrefix(joined, "auth can-i "):
170			return f.answerCanI(norm[2:])
171		case joined == "get namespace "+f.p.Namespace+" -o json":
172			return f.answerNamespace()
173		case joined == "get services -A -o json":
174			return f.answerServices()
175		case joined == "get nodes -o json":
176			return f.answerNodes()
177		default:
178			f.t.Errorf("unscripted kubectl call: %q", args)
179			return nil, []byte("unscripted call"), errFakeExit1
180		}
181	}
182	
183	func (r fakeReply) reply() ([]byte, []byte, error) {
184		return []byte(r.stdout), []byte(r.stderr), r.err
185	}
186	
187	func (f *fakeKubectl) answerCanI(args []string) ([]byte, []byte, error) {
188		var q canIQuery
189		var positional []string
190		for i := 0; i < len(args); i++ {
191			switch a := args[i]; {
192			case a == "-n":
193				if i+1 < len(args) {
194					i++
195					q.namespace = args[i]
196				}
197			case a == "-A":
198				q.allNamespaces = true
199			case a == "--subresource":
200				if i+1 < len(args) {
201					i++
202					q.subresource = args[i]
203				}
204			case strings.HasPrefix(a, "--subresource="):
205				q.subresource = strings.TrimPrefix(a, "--subresource=")
206			default:
207				positional = append(positional, a)
208			}
209		}
210		if len(positional) != 2 {
211			f.t.Errorf("auth can-i wants a verb and a resource, got %q", args)
212			return nil, []byte("bad can-i"), errFakeExit1
213		}
214		q.verb, q.resource = positional[0], positional[1]
215		if strings.Contains(q.resource, "/") {
216			// kubectl would read "pods/exec" as the object "exec" of the pods.
217			f.t.Errorf("auth can-i %q puts a subresource in the resource: use --subresource=<sub>", args)
218			return nil, []byte("error: resource names do not take a subresource, use --subresource"), errFakeExit1
219		}
220		if q.namespace != "" && q.namespace != f.p.Namespace {
221			f.t.Errorf("auth can-i %q asks about namespace %q, the run is about %q", args, q.namespace, f.p.Namespace)
222		}
223		f.asked = append(f.asked, q)
224		if f.denied[q.String()] {
225			return []byte("no\n"), nil, errFakeExit1
226		}
227		return []byte("yes\n"), nil, nil
228	}
229	
230	func (f *fakeKubectl) answerNamespace() ([]byte, []byte, error) {
231		if f.nsReply != nil {
232			return f.nsReply.reply()
233		}
234		if !f.nsPresent {
235			return nil, []byte("Error from server (NotFound): namespaces \"" + f.p.Namespace + "\" not found\n"), errFakeExit1
236		}
237		meta := map[string]any{"name": f.p.Namespace, "uid": "6b1f0f8e-0000-4000-8000-000000000001"}
238		if f.nsLabels != nil {
239			meta["labels"] = f.nsLabels
240		}
241		return f.mustJSON(map[string]any{
242			"apiVersion": "v1",
243			"kind":       "Namespace",
244			"metadata":   meta,
245			"status":     map[string]any{"phase": "Active"},
246		}), nil, nil
247	}
248	
249	func (f *fakeKubectl) answerServices() ([]byte, []byte, error) {
250		if f.servicesReply != nil {
251			return f.servicesReply.reply()
252		}
253		items := make([]any, 0, len(f.services))
254		for _, s := range f.services {
255			ports := make([]any, 0, len(s.nodePorts))
256			for i, np := range s.nodePorts {
257				ports = append(ports, map[string]any{"name": "p" + string(rune('0'+i)), "port": 80 + i, "targetPort": 8080 + i, "protocol": "TCP", "nodePort": np})
258			}
259			if len(ports) == 0 {
260				ports = append(ports, map[string]any{"port": 443, "protocol": "TCP", "targetPort": 6443})
261			}
262			kind := "ClusterIP"
263			if len(s.nodePorts) > 0 {
264				kind = "NodePort"
265			}
266			items = append(items, map[string]any{
267				"metadata": map[string]any{"name": s.name, "namespace": s.namespace},
268				"spec":     map[string]any{"type": kind, "ports": ports},
269			})
270		}
271		return f.mustJSON(map[string]any{"apiVersion": "v1", "kind": "List", "items": items}), nil, nil
272	}
273	
274	func (f *fakeKubectl) answerNodes() ([]byte, []byte, error) {
275		addresses := make([]any, 0, len(f.nodeAddresses))
276		for _, a := range f.nodeAddresses {
277			addresses = append(addresses, map[string]any{"type": a[0], "address": a[1]})
278		}
279		return f.mustJSON(map[string]any{
280			"apiVersion": "v1",
281			"kind":       "List",
282			"items": []any{map[string]any{
283				"metadata": map[string]any{"name": "datomir"},
284				"status":   map[string]any{"addresses": addresses},
285			}},
286		}), nil, nil
287	}
288	
289	func (f *fakeKubectl) mustJSON(v any) []byte {
290		f.t.Helper()
291		raw, err := json.Marshal(v)
292		if err != nil {
293			f.t.Fatalf("encoding a fake answer: %v", err)
294		}
295		return raw
296	}
297	
298	// normalizeArgs drops the request timeout and spells --all-namespaces as -A.
299	func normalizeArgs(args []string) []string {
300		out := make([]string, 0, len(args))
301		for _, a := range args {
302			switch {
303			case strings.HasPrefix(a, "--request-timeout"):
304			case a == "--all-namespaces":
305				out = append(out, "-A")
306			default:
307				out = append(out, a)
308			}
309		}
310		return out
311	}
312	
313	// flagsWithValue are the kubectl flags that take their value as the next argument.
314	var flagsWithValue = map[string]bool{
315		"-n": true, "--namespace": true, "-o": true, "--output": true,
316		"--context": true, "-f": true, "-l": true, "--selector": true, "-c": true,
317	}
318	
319	// verbOf returns the kubectl sub-command of args: the first positional argument.
320	// "auth can-i create pods" is therefore "auth", not "create".
321	func verbOf(args []string) string {
322		for i := 0; i < len(args); i++ {
323			switch a := args[i]; {
324			case flagsWithValue[a]:
325				i++
326			case strings.HasPrefix(a, "-"):
327			default:
328				return a
329			}
330		}
331		return ""
332	}
333	
334	var writeVerbs = []string{
335		"apply", "create", "delete", "patch", "exec", "label", "annotate", "replace",
336		"edit", "scale", "set", "rollout", "cp", "run", "expose", "taint", "drain",
337		"cordon", "uncordon", "autoscale", "debug", "attach",
338	}
339	
340	func isWriteVerb(verb string) bool { return slices.Contains(writeVerbs, verb) }
341	
342	// recordedWrites lists the calls the fake saw whose sub-command writes.
343	func (f *fakeKubectl) recordedWrites() []string {
344		var out []string
345		for _, c := range f.calls {
346			if isWriteVerb(verbOf(c.args)) {
347				out = append(out, strings.Join(c.args, " "))
348			}
349		}
350		return out
351	}
352	
353	func (f *fakeKubectl) callLines() []string {
354		out := make([]string, 0, len(f.calls))
355		for _, c := range f.calls {
356			out = append(out, strings.Join(normalizeArgs(c.args), " "))
357		}
358		return out
359	}
360	
361	// requireReadOnly fails when the preflight wrote anything, or sent a manifest on stdin.
362	func requireReadOnly(t *testing.T, f *fakeKubectl) {
363		t.Helper()
364		if writes := f.recordedWrites(); len(writes) > 0 {
365			t.Errorf("the preflight issued write calls: %q", writes)
366		}
367		for _, c := range f.calls {
368			if len(c.stdin) > 0 {
369				t.Errorf("the preflight sent stdin to %q", c.args)
370			}
371		}
372	}
373	
374	// requireCleanError checks what every failure of the bench promises: a
375	// *BenchError with a cause and a check, no password and no raw sub-process text.
376	func requireCleanError(t *testing.T, err error) *BenchError {
377		t.Helper()
378		var be *BenchError
379		if !errors.As(err, &be) {
380			t.Fatalf("error %T is not a *BenchError: %v", err, err)
381		}
382		if be.Cause == "" {
383			t.Error("the error has no Cause")
384		}
385		if !strings.Contains(be.Check, "kubectl") && !strings.Contains(be.Check, "mise") {
386			t.Errorf("Check %q names neither a kubectl command nor a mise task", be.Check)
387		}
388		msg := strings.ToLower(err.Error())
389		for _, banned := range []string{"password", fakeSecret} {
390			if strings.Contains(msg, banned) {
391				t.Errorf("message %q contains %q", err.Error(), banned)
392			}
393		}
394		return be
395	}
396	
397	// testOpName names the operations in sub-test titles and messages.
398	var testOpName = map[Op]string{OpUp: "up", OpProvision: "provision", OpDown: "down", OpStatus: "status", OpSeed: "seed"}
399	
400	// requiredCheck is a can-i the preflight must ask for an operation.
401	type requiredCheck struct {
402		verb, resource string
403		scope          string // "namespace" (-n <ns>), "cluster" (no -A) or "all" (-A)
404	}

